class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1
        items = [(-f, v) for v, f in freq.items()]
        heapq.heapify(items)
        res = []
        for i in range(k):
            res.append(heapq.heappop(items)[1])
        return res
